from collections import deque

def parse(s): return [[int(x) for x in l.split()] for l in s.splitlines()]
def bfs_demo(s,k,src,dst,observed):
 g=parse(s); H,W=len(g),len(g[0]);
 # legal tile positions when covered cells all background 1, target2, or current0
 def allowed(r,c):
  return 0<=r<H-k+1 and 0<=c<=W-k and all(g[i][j] in (0,1,2) for i in range(r,r+k) for j in range(c,c+k))
 q=deque([src]); dist={src:0}
 while q:
  p=q.popleft()
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   np=(p[0]+dr,p[1]+dc)
   if np not in dist and allowed(*np): dist[np]=dist[p]+1; q.append(np)
 minmd=min(abs(r-dst[0])+abs(c-dst[1]) for r,c in dist)
 closest=[p for p in dist if abs(p[0]-dst[0])+abs(p[1]-dst[1])==minmd]
 return len(dist), minmd, closest, {p:dist[p] for p in [observed,dst] if p in dist}
print(bfs_demo(demo1,2,(9,8),(0,1),(0,1)))
print(bfs_demo(demo2,2,(2,10),(12,1),(7,8)))
print(bfs_demo(demo3,3,(12,1),(1,0),(6,7)))

