def analyze(s,k,src,dst,obs):
 g=parse(s);H,W=len(g),len(g[0]);
 def ok(r,c):return 0<=r<=H-k and 0<=c<=W-k and all(g[i][j] in (0,1,2) for i in range(r,r+k) for j in range(c,c+k))
 q=deque([src]);d={src:0};adj={}
 while q:
  p=q.popleft(); nb=[]
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   x=(p[0]+dr,p[1]+dc)
   if ok(*x):
    nb.append(x)
    if x not in d:d[x]=d[p]+1;q.append(x)
  adj[p]=nb
 far=max(d.values()); fars=[p for p,x in d.items() if x==far]
 term=[p for p,nb in adj.items() if len(nb)==1]
 return {'states':len(d),'far':far,'fars':fars,'obsdist':d.get(obs),'obsdeg':len(adj.get(obs,[])),'terms':[(p,d[p]) for p in term]}
